begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
\ir auth-fixtures.psql
select plan(80);
-- Isolate fixtures even after an explicit integration run on this disposable DB.
delete from app_private.resend_webhook_receipts;
delete from app_private.email_deliveries;
delete from app_private.email_recipient_suppressions;
select ok(not has_table_privilege('anon','app_private.email_deliveries','SELECT'),'anonymous cannot read deliveries');
select ok(not has_table_privilege('authenticated','app_private.resend_webhook_receipts','SELECT'),'users cannot read receipts');
select ok(not has_table_privilege('service_role','app_private.email_recipient_suppressions','SELECT'),'service API has RPC-only suppression access');
select ok((select bool_and(relrowsecurity) from pg_class where oid in ('app_private.email_deliveries'::regclass,'app_private.resend_webhook_receipts'::regclass,'app_private.email_recipient_suppressions'::regclass)),'private tables have RLS');
select ok(not has_function_privilege('anon','public.prepare_application_email(uuid,text,text)','EXECUTE'),'anonymous cannot prepare');
select ok(not has_function_privilege('authenticated','public.record_resend_delivery_event(text,text,uuid,text,timestamptz,uuid)','EXECUTE'),'users cannot fabricate delivery events');
select ok(has_function_privilege('service_role','public.record_resend_delivery_event(text,text,uuid,text,timestamptz,uuid)','EXECUTE'),'service can record verified events');
select throws_ok($$select public.prepare_application_email('68000000-1111-4111-8111-111111111111',repeat('a',64),repeat('b',64))$$,'42501','email operation unavailable','JWT role required even for privileged execution');
select pg_temp.set_service_role_claims();
select throws_ok($$select public.prepare_application_email(null,repeat('a',64),repeat('b',64))$$,'22023','invalid delivery metadata','invalid metadata rejected');
select is(public.prepare_application_email('68000000-1111-4111-8111-111111111111',repeat('a',64),repeat('b',64))->>'status','ready','new send gets fenced lease');
select is(public.prepare_application_email('68000000-1111-4111-8111-111111111111',repeat('a',64),repeat('b',64))->>'status','busy','parallel send cannot obtain lease');
select is(public.prepare_application_email('68000000-1111-4111-8111-111111111111',repeat('c',64),repeat('b',64))->>'status','conflict','delivery recipient immutable');
select is(public.prepare_application_email('68000000-1111-4111-8111-111111111111',repeat('a',64),repeat('c',64))->>'status','conflict','delivery content immutable');
select ok(not public.finish_application_email('68000000-1111-4111-8111-111111111111','68000000-9999-4999-8999-999999999999','68000000-2222-4222-8222-222222222222'),'wrong token cannot finish');
select ok(public.record_resend_delivery_event('msg_early',repeat('d',64),'68000000-2222-4222-8222-222222222222','delivered',now(),'68000000-1111-4111-8111-111111111111'),'webhook before provider response is correlated by tag');
select is((select status from app_private.email_deliveries where delivery_id='68000000-1111-4111-8111-111111111111'),'delivered','early delivered persisted');
select ok(public.finish_application_email('68000000-1111-4111-8111-111111111111',(select claim_token from app_private.email_deliveries where delivery_id='68000000-1111-4111-8111-111111111111'),'68000000-2222-4222-8222-222222222222'),'matching completion succeeds');
select is((select status from app_private.email_deliveries where delivery_id='68000000-1111-4111-8111-111111111111'),'delivered','acceptance cannot downgrade delivery');
select is(public.prepare_application_email('68000000-1111-4111-8111-111111111111',repeat('a',64),repeat('b',64))->>'status','accepted','completed send is cached without HTTP retry');
select ok(not public.record_resend_delivery_event('msg_early',repeat('d',64),'68000000-2222-4222-8222-222222222222','delivered',now()),'duplicate receipt ignored');
select is((select count(*)::integer from app_private.resend_webhook_receipts),1,'one receipt for duplicate');
select ok(public.record_resend_delivery_event('msg_sent_late',repeat('e',64),'68000000-2222-4222-8222-222222222222','sent',now()-interval '1 minute'),'out of order sent acknowledged');
select is((select status from app_private.email_deliveries where delivery_id='68000000-1111-4111-8111-111111111111'),'delivered','out of order sent cannot regress delivery');
select ok(public.record_resend_delivery_event('msg_bounce',repeat('e',64),'68000000-2222-4222-8222-222222222222','bounced',now()),'bounce accepted');
select is((select reason from app_private.email_recipient_suppressions where recipient_hash=repeat('a',64)),'bounced','bounce suppresses local recipient hash');
select is(public.prepare_application_email('68000000-3333-4333-8333-333333333333',repeat('a',64),repeat('b',64))->>'status','suppressed','future different message cannot send');
select ok(public.record_resend_delivery_event('msg_delivered_late',repeat('e',64),'68000000-2222-4222-8222-222222222222','delivered',now()),'late delivery acknowledged');
select is((select status from app_private.email_deliveries where delivery_id='68000000-1111-4111-8111-111111111111'),'bounced','terminal bounce cannot regress');
select ok(public.record_resend_delivery_event('msg_complaint',repeat('e',64),'68000000-2222-4222-8222-222222222222','complained',now()),'complaint after delivery/bounce accepted');
select is((select reason from app_private.email_recipient_suppressions where recipient_hash=repeat('a',64)),'complained','stronger suppression reason persists');
select ok(public.record_resend_delivery_event('msg_other',repeat('e',64),'68000000-4444-4444-8444-444444444444','bounced',now()),'unmapped signed SMTP event acknowledged');
select is((select count(*)::integer from app_private.email_recipient_suppressions),1,'unmapped events cannot suppress');
select ok(public.record_resend_delivery_event('msg_conflicting_tag',repeat('e',64),'68000000-4444-4444-8444-444444444444','sent',now(),'68000000-1111-4111-8111-111111111111'),'conflicting tag ignored');
select is((select provider_message_id::text from app_private.email_deliveries where delivery_id='68000000-1111-4111-8111-111111111111'),'68000000-2222-4222-8222-222222222222','provider binding cannot change');
select throws_ok($$select public.record_resend_delivery_event('bad id',repeat('e',64),'68000000-2222-4222-8222-222222222222','delivered',now())$$,'22023','invalid delivery event','malformed ID rejected');
select throws_ok($$select public.record_resend_delivery_event('msg_future',repeat('e',64),'68000000-2222-4222-8222-222222222222','delivered',now()+interval '1 day')$$,'22023','invalid delivery event','invalid future event rejected');
select is(public.prepare_application_email('68000000-5555-4555-8555-555555555555',repeat('c',64),repeat('b',64))->>'status','ready','independent recipient can send');
select ok(public.finish_application_email('68000000-5555-4555-8555-555555555555',(select claim_token from app_private.email_deliveries where delivery_id='68000000-5555-4555-8555-555555555555'),null,'EMAIL_TIMEOUT',true),'transient failure releases lease');
select is(public.prepare_application_email('68000000-5555-4555-8555-555555555555',repeat('c',64),repeat('b',64))->>'status','ready','transient send may retry inside safe horizon');
update app_private.email_deliveries set lease_expires_at=now()-interval '1 second' where recipient_hash=repeat('c',64);
select ok(not public.finish_application_email('68000000-5555-4555-8555-555555555555',(select claim_token from app_private.email_deliveries where delivery_id='68000000-5555-4555-8555-555555555555'),'68000000-6666-4666-8666-666666666666'),'expired lease cannot finish');
update app_private.email_deliveries set first_attempt_at=now()-interval '23 hours' where recipient_hash=repeat('c',64);
select is(public.prepare_application_email('68000000-5555-4555-8555-555555555555',repeat('c',64),repeat('b',64))->>'status','expired','uncertain sends cannot cross provider idempotency horizon');
select is((public.email_delivery_health()->>'complaints')::integer,1,'health reports complaints');
select is((public.email_delivery_health()->>'healthy')::boolean,false,'complaint makes health unhealthy');
select ok(public.run_email_delivery_retention(500),'bounded retention runs');
update app_private.resend_webhook_receipts set received_at=now()-interval '31 days';
update app_private.email_deliveries set created_at=now()-interval '91 days',lease_expires_at=null;
select ok(public.run_email_delivery_retention(1),'bounded retention batch succeeds');
select is((select count(*)::integer from app_private.email_deliveries),1,'retention bound honored');
select is((select count(*)::integer from app_private.email_recipient_suppressions),1,'suppression survives registry cleanup');
select ok(public.run_email_delivery_retention(500),'remaining retention drains');
select is((select count(*)::integer from app_private.email_deliveries),0,'old metadata removed');
select is((select count(*)::integer from app_private.resend_webhook_receipts),0,'old receipts removed');
select is((public.email_delivery_health()->>'retentionHealthy')::boolean,true,'retention health clears once drained');
select throws_ok($$select public.run_email_delivery_retention(1001)$$,'22023','invalid email retention batch','unbounded retention refused');
select throws_ok($$select public.email_delivery_health(0,3000)$$,'22023','invalid email limits','invalid quota thresholds refused');
select pg_temp.create_auth_actor('68000000-7777-4777-8777-777777777777','68000000-8888-4888-8888-888888888888','synthetic@test.local');
insert into app_private.notification_outbox(recipient_user_id,notification_type,deduplication_key,payload,status,updated_at,delivered_at)
values('68000000-7777-4777-8777-777777777777','introduction_declined','email-retention-31',jsonb_build_object('secret','expired message'),'sent',now()-interval '31 days',now()-interval '31 days'),
('68000000-7777-4777-8777-777777777777','introduction_declined','email-retention-91','{}'::jsonb,'sent',now()-interval '91 days',now()-interval '91 days'),
('68000000-7777-4777-8777-777777777777','introduction_declined','email-retention-active',jsonb_build_object('secret','active message'),'queued',now()-interval '91 days',null);
select ok(public.run_email_delivery_retention(500),'queue cleanup included');
select is((select payload from app_private.notification_outbox where deduplication_key='email-retention-31'),'{}'::jsonb,'old terminal message material erased');
select is((select count(*)::integer from app_private.notification_outbox where deduplication_key='email-retention-91'),0,'old completed outbox row removed');
select is((select payload->>'secret' from app_private.notification_outbox where deduplication_key='email-retention-active'),'active message','active queue material is not destroyed');
select is((public.email_delivery_health()->>'overdueQueued')::integer,0,'age uses enqueue time, not old updated time');
update app_private.notification_outbox set created_at=now()-interval '11 minutes' where deduplication_key='email-retention-active';
select is((public.email_delivery_health()->>'overdueQueued')::integer,1,'old active queue raises operational signal');
select is(public.prepare_application_email('68000000-9999-4999-8999-999999999999',repeat('f',64),repeat('b',64))->>'status','ready','healthy new delivery tracked');
update app_private.email_deliveries set deferrals=3,lease_expires_at=null;
select is((public.email_delivery_health()->>'repeatedDeferrals')::integer,1,'repeated deferrals visible');
select is((public.email_delivery_health(1,1)->>'healthy')::boolean,false,'local quota threshold alerts');
update app_private.email_deliveries set created_at=now()-interval '2 hours';
select is((public.email_delivery_health()->>'unresolvedDelivery')::integer,1,'missing webhook or unresolved attempt alerts');
-- Manual queue recovery inside the safe window must remain usable after a
-- deterministic credential/configuration failure that never bound a provider ID.
select is(public.prepare_application_email('68100000-1111-4111-8111-111111111111',repeat('1',64),repeat('2',64))->>'status','ready','credential failure fixture gets lease');
select ok(public.finish_application_email('68100000-1111-4111-8111-111111111111',(select claim_token from app_private.email_deliveries where delivery_id='68100000-1111-4111-8111-111111111111'),null,'EMAIL_CREDENTIALS_REJECTED',false),'deterministic rejection recorded');
select is(public.prepare_application_email('68100000-1111-4111-8111-111111111111',repeat('1',64),repeat('2',64))->>'status','ready','authorized recovered job may retry same immutable request inside horizon');
update app_private.notification_outbox set status='failed',first_attempt_at=now(),last_error_code='EMAIL_DELIVERY_GUARD_UNAVAILABLE' where deduplication_key='email-retention-active';
select is(public.requeue_failed_relationship_notification((select notification_ref from app_private.notification_outbox where deduplication_key='email-retention-active')),'manual_review_required','uncertain persistence outcome needs per-item review');
select is(public.requeue_failed_relationship_notifications(100),0,'bulk recovery excludes uncertain guard outcome');
select is(public.requeue_failed_relationship_notification((select notification_ref from app_private.notification_outbox where deduplication_key='email-retention-active'),true),'queued','operator can release reviewed guard outcome; registry still enforces idempotency');
-- NAK68-R1-F1: accepted mail can later fail. That must not disappear from
-- operations health, even when the original message predates the rate window.
delete from app_private.notification_outbox where deduplication_key like 'email-retention-%';
delete from app_private.resend_webhook_receipts;
delete from app_private.email_deliveries;
select is((public.email_delivery_health()->>'healthy')::boolean,true,'failure regression begins healthy');
select is(public.prepare_application_email('68200000-1111-4111-8111-111111111111',repeat('3',64),repeat('4',64))->>'status','ready','failure regression gets lease');
select ok(public.finish_application_email('68200000-1111-4111-8111-111111111111',(select claim_token from app_private.email_deliveries where delivery_id='68200000-1111-4111-8111-111111111111'),'68200000-2222-4222-8222-222222222222'),'failure regression binds accepted provider message');
select ok(public.record_resend_delivery_event('msg_failed_health',repeat('d',64),'68200000-2222-4222-8222-222222222222','failed',now()),'provider failure is received');
select is((public.email_delivery_health()->>'failedDelivery')::integer,1,'provider delivery failure is observable');
select is((public.email_delivery_health()->>'healthy')::boolean,false,'provider delivery failure makes aggregate health unhealthy');
update app_private.email_deliveries set created_at=now()-interval '2 days';
select is((public.email_delivery_health()->>'failedDelivery')::integer,1,'late provider failure is counted by recent receipt');
select ok(public.record_resend_delivery_event('msg_failed_then_delivered',repeat('d',64),'68200000-2222-4222-8222-222222222222','delivered',now()),'stronger delivered outcome is recorded');
select is((public.email_delivery_health()->>'failedDelivery')::integer,0,'resolved provider failure does not falsely alert');
select is((public.email_delivery_health()->>'healthy')::boolean,true,'stronger delivered outcome restores clean health');
select is((select last_error_code from app_private.email_deliveries where delivery_id='68200000-1111-4111-8111-111111111111'),null::text,'stronger delivered outcome clears old transient failure code');
select * from finish();
rollback;
